SELECT COUNT(*), SUM(qty), ROUND(SUM(amount), 2), MIN(amount), MAX(amount) FROM orders;
SELECT region, COUNT(*) AS n, ROUND(AVG(amount), 2) AS avg FROM orders GROUP BY region ORDER BY n DESC, region;
SELECT customer, COUNT(*) AS n, SUM(qty) FROM orders GROUP BY customer HAVING COUNT(*) >= 5 ORDER BY n DESC, customer LIMIT 10;
